import { forwardRef, useCallback, useEffect, useRef, useState } from 'react';
import type { ListGroup } from '@arvo/core';
import ArvoActionMenu from '../ActionMenu/ActionMenu';
import type { MenuItemData } from '../ActionMenu/ActionMenu';
import { useTooltip, type TooltipProp } from '../../hooks/useTooltip';
import type { MenuSearchProp } from '../../types/menu-search';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ArvoSplitIconButtonProps
  extends Omit<
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    'disabled' | 'type' | 'onSelect'
  > {
  icon: string;
  /**
   * Tooltip content for the action segment. Required because the action is
   * icon-only -- the value also drives `aria-label`.
   */
  tooltip: TooltipProp;
  variant?: 'primary' | 'secondary' | 'tertiary';
  size?: 'sm' | 'md' | 'lg';
  isDisabled?: boolean;
  isActionDisabled?: boolean;
  isTriggerDisabled?: boolean;
  isLoading?: boolean;
  items: MenuItemData[] | ListGroup<MenuItemData>[];
  /** Enable search with defaults (`true`) or pass a config object. */
  search?: MenuSearchProp;
  placement?: 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end';
  maxHeight?: string;
  hasGroupDividers?: boolean;
  closeOnSelect?: boolean;
  /**
   * Accessible name for the trigger (caret) segment, exposed via aria-label.
   * Default: "Show options". Consumers should pass something contextual like
   * "Filter options" or "Sort options".
   */
  triggerLabel?: string;
  onAction?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onSelect?: (item: MenuItemData, index: number) => boolean | void;
  onOpen?: () => boolean | void;
  onClose?: () => boolean | void;
  onOpenChange?: (isOpen: boolean) => void;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

const ArvoSplitIconButton = forwardRef<
  HTMLButtonElement,
  ArvoSplitIconButtonProps
>(function ArvoSplitIconButton(
  {
    icon,
    tooltip,
    variant = 'primary',
    size = 'md',
    isDisabled = false,
    isActionDisabled = false,
    isTriggerDisabled = false,
    isLoading = false,
    items,
    search,
    placement = 'bottom-end',
    maxHeight,
    hasGroupDividers = true,
    closeOnSelect = true,
    triggerLabel = 'Show options',
    className,
    onAction,
    onSelect,
    onOpen,
    onClose,
    onOpenChange,
    onClick,
    onFocus,
    onBlur,
    onKeyDown,
    ...rest
  },
  ref,
) {
  const wrapperRef = useRef<HTMLDivElement | null>(null);
  const actionRef = useRef<HTMLButtonElement | null>(null);
  const triggerRef = useRef<HTMLButtonElement | null>(null);

  // Menu size derived from trigger size (sm trigger -> sm menu, md/lg -> md).
  const menuSize: 'sm' | 'md' = size === 'sm' ? 'sm' : 'md';

  // Dev-time warning: tooltip is required for SplitIconButton because the
  // action segment has no visible label; without it screen readers cannot name
  // the control.
  useEffect(() => {
    if (process.env.NODE_ENV !== 'production' && !tooltip) {
      console.warn(
        'ArvoSplitIconButton: `tooltip` is required so the action segment has an accessible name (it is also rendered as the visual tooltip).',
      );
    }
  }, [tooltip]);

  // -- Tooltip wiring (action segment only; the caret is internal) ------
  useTooltip({ triggerRef: actionRef, tooltip });

  // Resolve tooltip text for the static aria-label on the action segment.
  // useTooltip wires the visual tooltip via the overlay system, but the
  // action segment must always have an accessible name even before that
  // wiring attaches (and in tests where the tooltip portal isn't realised).
  const tooltipLabel =
    typeof tooltip === 'string'
      ? tooltip
      : tooltip != null
      ? tooltip.content
      : undefined;

  // -- Open state (drives wrapper .open class for caret rotation) -------
  const [isOpen, setIsOpen] = useState(false);

  // -- Custom event dispatch (always on the wrapper) --------------------
  const dispatchWrapperEvent = useCallback(
    (name: string, detail: unknown, cancelable = true) => {
      wrapperRef.current?.dispatchEvent(
        new CustomEvent(name, { bubbles: true, cancelable, detail }),
      );
    },
    [],
  );

  // -- Open / close pipeline (from internal ActionMenu) -----------------
  const handleOpenChange = useCallback(
    (next: boolean) => {
      setIsOpen(next);
      if (next) {
        dispatchWrapperEvent('split-icon-btn:open', {});
      } else {
        dispatchWrapperEvent('split-icon-btn:close', {});
      }
      onOpenChange?.(next);
    },
    [dispatchWrapperEvent, onOpenChange],
  );

  // -- Menu item selection ----------------------------------------------
  const handleMenuSelect = useCallback(
    (item: MenuItemData, index: number) => {
      dispatchWrapperEvent('split-icon-btn:select', { item, index });
      return onSelect?.(item, index);
    },
    [dispatchWrapperEvent, onSelect],
  );

  // -- Disabled flags per segment ---------------------------------------
  const actionDisabled = isDisabled || isActionDisabled || isLoading;
  const triggerDisabled = isDisabled || isTriggerDisabled || isLoading;

  // -- Action segment click ---------------------------------------------
  const handleActionClick = useCallback(
    (event: React.MouseEvent<HTMLButtonElement>) => {
      if (actionDisabled) return;
      dispatchWrapperEvent('split-icon-btn:action', {});
      onAction?.(event);
      onClick?.(event);
    },
    [actionDisabled, dispatchWrapperEvent, onAction, onClick],
  );

  // -- Keyboard on the action segment -----------------------------------
  // ArrowDown and Alt+ArrowDown both open the menu without first tabbing to
  // the caret trigger. Programmatic click on the trigger reuses ArvoActionMenu's
  // open + focus-trap flow.
  const handleActionKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLButtonElement>) => {
      onKeyDown?.(event);
      if (event.defaultPrevented) return;
      if (
        (event.key === 'ArrowDown' || (event.altKey && event.key === 'ArrowDown')) &&
        !actionDisabled
      ) {
        event.preventDefault();
        triggerRef.current?.click();
      }
    },
    [actionDisabled, onKeyDown],
  );

  // -- Forwarded + internal action ref merge ----------------------------
  const mergeActionRef = useCallback(
    (node: HTMLButtonElement | null) => {
      actionRef.current = node;
      if (typeof ref === 'function') {
        ref(node);
      } else if (ref) {
        (ref as React.MutableRefObject<HTMLButtonElement | null>).current = node;
      }
    },
    [ref],
  );

  // -- Class composition ------------------------------------------------
  const wrapperClasses = [
    'arvo-split-icon-btn',
    `arvo-split-icon-btn--${variant}`,
    `arvo-split-icon-btn--${size}`,
    isOpen && 'open',
    isLoading && 'loading',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  const actionSegmentClasses = [
    'arvo-icon-btn',
    `arvo-btn--${variant}`,
    `arvo-btn--${size}`,
    'arvo-split-icon-btn__action',
  ].join(' ');

  const triggerSegmentClasses = [
    'arvo-btn',
    `arvo-btn--${variant}`,
    `arvo-btn--${size}`,
    'arvo-split-icon-btn__trigger',
  ].join(' ');

  // -- Trigger element (cloned by ArvoActionMenu) -----------------------
  // The caret button is an internal segment of the SplitIconButton. It does
  // not expose a focus/blur contract -- consumers attach onFocus/onBlur to
  // the action segment instead.
  const triggerElement = (
    <button
      ref={triggerRef}
      type="button"
      className={triggerSegmentClasses}
      disabled={triggerDisabled}
      aria-label={triggerLabel}
    >
      <span
        className="arvo-split-icon-btn__caret o9con o9con-angle-down"
        aria-hidden="true"
      />
    </button>
  );

  return (
    <div
      ref={wrapperRef}
      className={wrapperClasses}
      role="group"
      aria-disabled={isDisabled || undefined}
      aria-busy={isLoading || undefined}
    >
      <button
        {...rest}
        ref={mergeActionRef}
        type="button"
        className={actionSegmentClasses}
        disabled={actionDisabled}
        aria-label={tooltipLabel}
        onClick={handleActionClick}
        onKeyDown={handleActionKeyDown}
        onFocus={onFocus}
        onBlur={onBlur}
      >
        <span
          className={`arvo-split-icon-btn__icon o9con o9con-${icon}`}
          aria-hidden="true"
        />
      </button>
      <ArvoActionMenu
        trigger={triggerElement}
        items={items}
        size={menuSize}
        placement={placement}
        search={search}
        maxHeight={maxHeight}
        hasGroupDividers={hasGroupDividers}
        closeOnSelect={closeOnSelect}
        isDisabled={isDisabled || isTriggerDisabled || isLoading}
        isLoading={false}
        onOpen={onOpen}
        onClose={onClose}
        onSelect={handleMenuSelect}
        onOpenChange={handleOpenChange}
      />
    </div>
  );
});

export default ArvoSplitIconButton;
